#!/bin/bash
# GENERATED by generate-quadlets.py from quadlets/TAP network policy readiness — DO NOT EDIT

set -euo pipefail

READY_DIR=/run/nas-krun-network
READY_FILE="${READY_DIR}/policy-ready"
TAPS=("krun-51110" "krun-51120" "krun-51210" "krun-51220" "krun-51230" "krun-51240" "krun-51250" "krun-51260" "krun-51310")
GATEWAYS=("10.253.1.1/30" "10.253.2.1/30" "10.253.3.1/30" "10.253.4.1/30" "10.253.5.1/30" "10.253.6.1/30" "10.253.7.1/30" "10.253.8.1/30" "10.253.9.1/30")
USER_UNITS=("user@51110.service" "user@51120.service" "user@51210.service" "user@51220.service" "user@51230.service" "user@51240.service" "user@51250.service" "user@51260.service" "user@51310.service")

quiesce_guests() {
    rm -f "${READY_FILE}"
    systemctl stop "${USER_UNITS[@]}"
    for unit in "${USER_UNITS[@]}"; do
        if systemctl is-active --quiet "${unit}"; then
            echo "Refusing to remove krun network policy while ${unit} is active" >&2
            return 1
        fi
    done
}

publish_readiness() {
    trap 'rm -f "${READY_FILE}"' ERR
    install -d -o root -g root -m 0755 "${READY_DIR}"
    rm -f "${READY_FILE}"

    /usr/lib/systemd/systemd-networkd-wait-online --quiet --timeout=60 \
        --ipv4 --interface="krun-51110:off" --interface="krun-51120:off" --interface="krun-51210:off" --interface="krun-51220:off" --interface="krun-51230:off" --interface="krun-51240:off" --interface="krun-51250:off" --interface="krun-51260:off" --interface="krun-51310:off"

    for index in "${!TAPS[@]}"; do
        ip -4 -o address show dev "${TAPS[$index]}" \
            | grep -Fq " ${GATEWAYS[$index]} "
    done

    nft list chain inet filter nas_krun_input >/dev/null
    nft list chain inet filter nas_krun_forward >/dev/null
    nft list table ip nas_krun_nat >/dev/null

    printf '%s\n' "$(cat /proc/sys/kernel/random/boot_id)" \
        > "${READY_FILE}.tmp"
    chown root:root "${READY_FILE}.tmp"
    chmod 0644 "${READY_FILE}.tmp"
    mv -f "${READY_FILE}.tmp" "${READY_FILE}"
    systemctl start "${USER_UNITS[@]}"
    trap - ERR
}

case "${1:-}" in
    publish)
        publish_readiness
        ;;
    quiesce)
        quiesce_guests
        ;;
    quiesce-and-flush)
        quiesce_guests
        nft flush ruleset
        ;;
    *)
        echo "usage: $0 publish|quiesce|quiesce-and-flush" >&2
        exit 2
        ;;
esac
